// Package md provides helper functions for generating Markdown content programmatically.
//
// It includes utilities for text formatting, creating lists, blockquotes, code blocks,
// links, images, and more.
//
// Highlights:
// - Supports basic Markdown syntax such as bold, italic, strikethrough, headers, and lists.
// - Manages multiline support in lists (e.g., bullet, ordered, and todo lists).
// - Includes advanced helpers like inline images with links and nested list prefixes.
//
// For a comprehensive example of how to use these helpers, see:
// https://gno.land/r/docs/moul_md
//
// # Sanitization contract
//
// Some helpers in this package sanitize their user-derived arguments
// INTERNALLY (via p/nt/markdown/sanitize/v0). When using these, pass
// raw user input — do NOT pre-wrap with sanitize.*, or you will
// double-wrap (the escapers are not idempotent and double-wrap is a
// bug):
//
//	Link, UserLink, Image, InlineImageWithLink, FootnoteDefinition,
//	LinkReferenceDefinition, CollapsibleSection (title only),
//	InlineCode, CodeBlock, LanguageCodeBlock, Blockquote
//
// The other helpers DO NOT sanitize — they are pure builders that
// wrap their input in markdown chrome. User-derived input reaches
// the output unmodified, so callers MUST wrap with sanitize.* at the
// call site:
//
//	Bold, Italic, Strikethrough, H1-H6, BulletList, BulletItem,
//	OrderedList, TodoList, TodoItem, Nested, Paragraph, Columns,
//	ColumnsN, HorizontalRule
//
// Examples:
//
//	// Sanitizing helper — pass raw:
//	out += md.Link(post.Title, post.URL)                                 // good
//	out += md.Link(sanitize.InlineText(post.Title), sanitize.URL(post.URL)) // BAD: double-wrap
//
//	// Non-sanitizing helper — wrap once:
//	out += md.H2(sanitize.InlineText(post.Title))                        // good
//	out += md.H2(post.Title)                                             // BAD: raw user input
//	out += md.H2(sanitize.InlineText(sanitize.InlineText(post.Title)))   // BAD: double-wrap
//
// Composition: outputs of sanitizing helpers are safe markdown chrome
// and can be embedded inside non-sanitizing helpers freely:
//
//	out += md.H2(md.Link(post.Title, post.URL))   // good — H2 doesn't re-escape Link's output
//
// The reverse is unsafe: do NOT embed a non-sanitizing helper's
// markdown chrome inside a sanitizing helper's arg, or the inner
// markdown gets re-escaped:
//
//	out += md.Link(md.Bold(post.Title), post.URL) // BAD: Link's internal sanitize
//	                                              // escapes the ** chars from md.Bold
package md

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// Bold returns bold text for markdown.
// Example: Bold("foo") => "**foo**"
func Bold(text string) string {
	return "**" + text + "**"
}

// Italic returns italicized text for markdown.
// Example: Italic("foo") => "*foo*"
func Italic(text string) string {
	return "*" + text + "*"
}

// Strikethrough returns strikethrough text for markdown.
// Example: Strikethrough("foo") => "~~foo~~"
func Strikethrough(text string) string {
	return "~~" + text + "~~"
}

// H1 returns a level 1 header for markdown.
// Example: H1("foo") => "# foo\n"
func H1(text string) string {
	return "# " + text + "\n"
}

// H2 returns a level 2 header for markdown.
// Example: H2("foo") => "## foo\n"
func H2(text string) string {
	return "## " + text + "\n"
}

// H3 returns a level 3 header for markdown.
// Example: H3("foo") => "### foo\n"
func H3(text string) string {
	return "### " + text + "\n"
}

// H4 returns a level 4 header for markdown.
// Example: H4("foo") => "#### foo\n"
func H4(text string) string {
	return "#### " + text + "\n"
}

// H5 returns a level 5 header for markdown.
// Example: H5("foo") => "##### foo\n"
func H5(text string) string {
	return "##### " + text + "\n"
}

// H6 returns a level 6 header for markdown.
// Example: H6("foo") => "###### foo\n"
func H6(text string) string {
	return "###### " + text + "\n"
}

// BulletList returns a bullet list for markdown.
// Example: BulletList([]string{"foo", "bar"}) => "- foo\n- bar\n"
func BulletList(items []string) string {
	var sb strings.Builder
	for _, item := range items {
		sb.WriteString(BulletItem(item))
	}
	return sb.String()
}

// BulletItem returns a bullet item for markdown.
// Example: BulletItem("foo") => "- foo\n"
func BulletItem(item string) string {
	var sb strings.Builder
	lines := strings.Split(item, "\n")
	sb.WriteString("- " + lines[0] + "\n")
	for _, line := range lines[1:] {
		sb.WriteString("  " + line + "\n")
	}
	return sb.String()
}

// OrderedList returns an ordered list for markdown.
// Example: OrderedList([]string{"foo", "bar"}) => "1. foo\n2. bar\n"
func OrderedList(items []string) string {
	var sb strings.Builder
	for i, item := range items {
		lines := strings.Split(item, "\n")
		sb.WriteString(strconv.Itoa(i+1) + ". " + lines[0] + "\n")
		for _, line := range lines[1:] {
			sb.WriteString("   " + line + "\n")
		}
	}
	return sb.String()
}

// TodoList returns a list of todo items with checkboxes for markdown.
// Example: TodoList([]string{"foo", "bar\nmore bar"}, []bool{true, false}) => "- [x] foo\n- [ ] bar\n  more bar\n"
func TodoList(items []string, done []bool) string {
	var sb strings.Builder
	for i, item := range items {
		sb.WriteString(TodoItem(item, done[i]))
	}
	return sb.String()
}

// TodoItem returns a todo item with checkbox for markdown.
// Example: TodoItem("foo", true) => "- [x] foo\n"
func TodoItem(item string, done bool) string {
	var sb strings.Builder
	checkbox := " "
	if done {
		checkbox = "x"
	}
	lines := strings.Split(item, "\n")
	sb.WriteString("- [" + checkbox + "] " + lines[0] + "\n")
	for _, line := range lines[1:] {
		sb.WriteString("  " + line + "\n")
	}
	return sb.String()
}

// Nested prefixes each line with a given prefix, enabling nested lists.
// Example: Nested("- foo\n- bar", "  ") => "  - foo\n  - bar\n"
func Nested(content, prefix string) string {
	lines := strings.Split(content, "\n")
	for i := range lines {
		if strings.TrimSpace(lines[i]) != "" {
			lines[i] = prefix + lines[i]
		}
	}
	return strings.Join(lines, "\n")
}

// Blockquote returns the text as a CommonMark blockquote.
// Example: Blockquote("foo\nbar") => "\n> foo\n> bar\n\n"
//
// Delegates to sanitize.Blockquote, which cleans the content (bidi-strip,
// CR/CRLF/U+2028/U+2029/NEL line-ending normalize, LRD strip, ref-link
// escape, block-marker escape, fence auto-close), line-prefixes each
// line with "> ", and wraps with "\n" / "\n\n" so the quote opens
// cleanly and cannot pull appended chrome into the quote via CM §5.2
// lazy continuation. Callers do NOT need to pre-wrap the input.
func Blockquote(text string) string {
	return sanitize.Blockquote(text)
}

// InlineCode wraps the given text as a CommonMark inline code span.
// Example: InlineCode("foo") => "`foo`"
//
// Delegates to sanitize.InlineCode, which cleans the input (bidi-strip,
// CR/CRLF + NEL + U+2028/U+2029 folded to single space, NUL→U+FFFD)
// and picks a backtick-run length that outscans any internal backticks.
// Callers do NOT need to pre-wrap the input.
func InlineCode(code string) string {
	return sanitize.InlineCode(code)
}

// CodeBlock creates a markdown code block.
// Example: CodeBlock("foo") => "```\nfoo\n```"
//
// Delegates to sanitize.CodeBlock, which cleans the content (bidi-strip,
// CR/CRLF normalize, NEL/U+2028/U+2029 fold, NUL→U+FFFD) and picks a
// fence wide enough to outscan any backticks in content. Callers do NOT
// need to pre-wrap content with another sanitize helper.
func CodeBlock(content string) string {
	return sanitize.CodeBlock(content)
}

// LanguageCodeBlock creates a markdown code block with language-specific syntax highlighting.
// Example: LanguageCodeBlock("go", "foo") => "```go\nfoo\n```"
//
// Delegates to sanitize.LanguageCodeBlock, which validates the language
// tag (charset ^[a-zA-Z0-9_+-]{1,32}$, falling back to a tagless fence
// if invalid) and cleans the content as CodeBlock does. Callers do NOT
// need to pre-wrap either argument.
func LanguageCodeBlock(language, content string) string {
	return sanitize.LanguageCodeBlock(language, content)
}

// HorizontalRule returns a horizontal rule for markdown.
// Example: HorizontalRule() => "---\n"
func HorizontalRule() string {
	return "---\n"
}

// Link returns a hyperlink for markdown.
// Example: Link("foo", "http://example.com") => "[foo](http://example.com)"
//
// The text and url args are sanitized internally — text via
// sanitize.InlineText, url via sanitize.URL (allowlists http/https/
// mailto/relative/fragment; rejects javascript:, data:, blob:, etc.).
// Callers do NOT need to pre-wrap either argument; double-wrapping is
// a bug (the inline-text escaper is non-idempotent).
//
// If the URL fails the scheme allowlist, the href is rendered empty —
// the link becomes inert rather than carrying a malicious destination.
func Link(text, url string) string {
	return "[" + sanitize.InlineText(text) + "](" + sanitize.URL(url) + ")"
}

// UserLink returns a user profile link for markdown.
// Example: UserLink("moul") => "[@moul](/u/moul)"
// Example: UserLink("g1blah...") => "[g1blah...](/u/g1blah...)"
//
// Validates the user identifier — if it matches the gno bech32 address
// pattern (g1...), produces an address-style link; otherwise tries the
// r/sys/users-charset username and produces an @-style link. Returns
// "" if the identifier matches neither — callers should treat "" as
// "skip the user mention" rather than emit a broken link.
func UserLink(user string) string {
	if addr := sanitize.BechString(user, "g"); addr != "" {
		return "[" + addr + "](/u/" + addr + ")"
	}
	if name := sanitize.UserName(user); name != "" {
		return "[@" + name + "](/u/" + name + ")"
	}
	return ""
}

// InlineImageWithLink creates an inline image wrapped in a hyperlink for markdown.
// Example: InlineImageWithLink("alt text", "image-url", "link-url") => "[![alt text](image-url)](link-url)"
//
// altText and imageUrl are sanitized via Image (sanitize.InlineText +
// sanitize.ImageURL); linkUrl is sanitized via sanitize.URL. Callers
// do NOT need to pre-wrap any argument.
func InlineImageWithLink(altText, imageUrl, linkUrl string) string {
	return "[" + Image(altText, imageUrl) + "](" + sanitize.URL(linkUrl) + ")"
}

// Image returns an image for markdown.
// Example: Image("foo", "http://example.com") => "![foo](http://example.com)"
//
// altText is sanitized via sanitize.InlineText, url via
// sanitize.ImageURL (allowlists http/https/relative + data:image/*;
// rejects mailto:, javascript:, data:text/html, etc.). Callers do NOT
// need to pre-wrap either argument.
func Image(altText, url string) string {
	return "![" + sanitize.InlineText(altText) + "](" + sanitize.ImageURL(url) + ")"
}

// FootnoteDefinition emits a GFM footnote definition — `[^name]: body` —
// for a footnote that is referenced elsewhere in the document by
// `[^name]`.
//
// Example: FootnoteDefinition("note1", "Long form of the citation.")
// renders as:
//
//	[^note1]:
//	    Long form of the citation.
//
// The `name` is validated as a FootnoteLabel (^[A-Za-z0-9_-]{1,64}$);
// `text` is user-supplied multi-paragraph prose, sanitized via Block.
// An invalid name or empty body returns "".
//
// Delegates to sanitize.FootnoteDefinition. Callers do NOT need to
// pre-wrap either argument.
func FootnoteDefinition(name, text string) string {
	return sanitize.FootnoteDefinition(name, text)
}

// LinkReferenceDefinition emits a CommonMark link reference definition
// (CM §4.7) — `[label]: url "title"` — for a reference link that is
// invoked elsewhere by `[text][label]` or by the shortcut form
// `[label]`.
//
// Example: LinkReferenceDefinition("r/docs/help", "/r/docs/help", "")
// renders as:
//
//	[r/docs/help]: /r/docs/help
//
// The `label` is validated as a FootnoteLabel (^[A-Za-z0-9_-]{1,64}$);
// `url` is sanitized via URL (allowlist); `title` is sanitized via
// LinkTitle. An invalid label or rejected URL returns "".
//
// Realms should choose a namespaced label using dashes
// (e.g. `r-myrealm-help`) so that shortcut-reference invocations from
// user content can't collide with bare words a user is likely to write.
// `/` is not in the FootnoteLabel charset.
//
// Delegates to sanitize.LinkReferenceDefinition. Callers do NOT need to
// pre-wrap any argument.
func LinkReferenceDefinition(label, url, title string) string {
	return sanitize.LinkReferenceDefinition(label, url, title)
}

// Paragraph wraps the given text in a Markdown paragraph.
// Example: Paragraph("foo") => "foo\n"
func Paragraph(content string) string {
	return content + "\n\n"
}

// CollapsibleSection creates a collapsible section for markdown using
// HTML <details> and <summary> tags.
// Example:
// CollapsibleSection("Click to expand", "Hidden content")
// =>
// <details><summary>Click to expand</summary>
//
// Hidden content
// </details>
//
// The title argument is sanitized via sanitize.HTMLEscape (it lands in
// an HTML element body inside <summary>, not a markdown context — so
// HTML entity escaping is the correct policy, not markdown backslash
// escaping). The content argument is passed through unchanged because
// <details> with a blank-line-separated body allows markdown inside
// (CM §4.6); callers must pre-wrap content with sanitize.Block if it
// derives from user input.
func CollapsibleSection(title, content string) string {
	return "<details><summary>" + sanitize.HTMLEscape(title) + "</summary>\n\n" + content + "\n</details>\n"
}

// EscapeURL escapes characters in a URL for use in markdown link syntax.
//
// Deprecated: use sanitize.URL (for link href) or sanitize.ImageURL
// (for image src) directly. EscapeURL previously only percent-encoded
// ( and ) and did not validate the URL scheme — a security footgun
// (EscapeURL("javascript:alert(1)") returned a working XSS payload).
// It now delegates to sanitize.URL, which allowlists schemes (rejects
// javascript:, data:text/html, vbscript:, blob:, etc.) and
// percent-encodes all unsafe bytes (including the ( ) this function
// handled). The other helpers in this package (Link, UserLink, Image,
// InlineImageWithLink) sanitize their URL args internally now, so you
// rarely need to call any URL-escape helper directly.
//
// Behavior change vs. the original implementation: invalid schemes
// now return "" instead of passing through with ( ) escaped. Non-ASCII
// bytes get percent-encoded to standard RFC 3986 wire form instead of
// passing through as raw UTF-8.
func EscapeURL(url string) string {
	return sanitize.URL(url)
}

// EscapeText escapes special Markdown characters in regular text for
// use in inline contexts.
//
// Deprecated: use sanitize.InlineText directly. EscapeText was
// INCOMPLETE — it missed \, #, <, & and did not strip bidi/zero-width
// characters, replace NUL with U+FFFD, or normalize line endings.
// User input could inject backslash escapes (\* cancels neighboring
// escapes), autolinks (<https://x>), raw HTML (<script>), HTML entity
// references (&amp;), and bidi spoofing (RLO before an address). It
// now delegates to sanitize.InlineText. The other helpers in this
// package (Link, UserLink, Image, InlineImageWithLink, CollapsibleSection)
// sanitize their text args internally now, so you rarely need to call
// any inline-text-escape helper directly.
//
// Behavior change vs. the original implementation: \, #, <, & are now
// escaped; | is no longer escaped (the original was over-escaping —
// outside GFM table-cell context, | is markdown-inert; for table
// cells use sanitize.TableCell which adds the | escape on top of the
// inline-text set). Bidi controls are stripped, NUL becomes U+FFFD,
// and line endings normalize.
func EscapeText(text string) string {
	return sanitize.InlineText(text)
}

// Columns returns a formatted row of columns using the Gno syntax.
// If you want a specific number of columns per row (<=4), use ColumnsN.
// Check /r/docs/markdown#columns for more info.
// If padded=true & the final <gno-columns> tag is missing column content, an empty
// column element will be placed to keep the cols per row constant.
// Padding works only with colsPerRow > 0.
//
// Example:
//
//	Columns([]string{"A", "B"}, false)
//	// Returns:
//	// <gno-columns>
//	// A
//	// <gno-columns-sep>
//	// B
//	// </gno-columns>
func Columns(contentByColumn []string, padded bool) string {
	if len(contentByColumn) == 0 {
		return ""
	}
	maxCols := 4
	if padded && len(contentByColumn)%maxCols != 0 {
		missing := maxCols - len(contentByColumn)%maxCols
		contentByColumn = append(contentByColumn, make([]string, missing)...)
	}

	var sb strings.Builder
	sb.WriteString("<gno-columns>\n")

	for i, column := range contentByColumn {
		if i > 0 {
			sb.WriteString("<gno-columns-sep>\n")
		}
		sb.WriteString(column + "\n")
	}

	sb.WriteString("</gno-columns>\n")
	return sb.String()
}

const maxColumnsPerRow = 4

// ColumnsN splits content into multiple rows of N columns each and formats them.
// If colsPerRow <= 0, all items are placed in one <gno-columns> block.
// If padded=true & the final <gno-columns> tag is missing column content, an empty
// column element will be placed to keep the cols per row constant.
// Padding works only with colsPerRow > 0.
// Note: On standard-size screens, gnoweb handles a max of 4 cols per row.
//
// Example:
//
//	ColumnsN([]string{"A", "B", "C"}, 2, false)
//	// Returns:
//	// <gno-columns>
//	// A
//	// <gno-columns-sep>
//	// B
//	// </gno-columns>
//	// <gno-columns>
//	// C
//	// </gno-columns>
func ColumnsN(content []string, colsPerRow int, padded bool) string {
	if len(content) == 0 {
		return ""
	}
	if colsPerRow <= 0 {
		return Columns(content, padded)
	}

	var sb strings.Builder
	// Case 2: Multiple blocks with max 4 columns
	for i := 0; i < len(content); i += colsPerRow {
		end := i + colsPerRow
		if end > len(content) {
			end = len(content)
		}
		row := content[i:end]

		// Add padding if needed
		if padded && len(row) < colsPerRow {
			row = append(row, make([]string, colsPerRow-len(row))...)
		}

		sb.WriteString(Columns(row, false))
	}
	return sb.String()
}

// Package mdtable provides a simple way to create Markdown tables.
//
// Example usage:
//
//	import "gno.land/p/moul/mdtable/v0"
//
//	func Render(path string) string {
//	    table := mdtable.Table{
//	        Headers: []string{"ID", "Title", "Status", "Date"},
//	    }
//	    table.Append([]string{"#1", "Add a new validator", "succeed", "2024-01-01"})
//	    table.Append([]string{"#2", "Change parameter", "timed out", "2024-01-02"})
//	    return table.String()
//	}
//
// Output:
//
//	| ID | Title | Status | Date |
//	| --- | --- | --- | --- |
//	| #1 | Add a new validator | succeed | 2024-01-01 |
//	| #2 | Change parameter | timed out | 2024-01-02 |
package mdtable

import (
	"strings"
)

type Table struct {
	Headers []string
	Rows    [][]string
	// XXX: optional headers alignment.
}

func (t *Table) Append(row []string) {
	t.Rows = append(t.Rows, row)
}

func (t Table) String() string {
	// XXX: switch to using text/tabwriter when porting to Gno to support
	// better-formatted raw Markdown output.

	if len(t.Headers) == 0 && len(t.Rows) == 0 {
		return ""
	}

	var sb strings.Builder

	if len(t.Headers) == 0 {
		t.Headers = make([]string, len(t.Rows[0]))
	}

	// Print header.
	sb.WriteString("| " + strings.Join(t.Headers, " | ") + " |\n")
	sb.WriteString("|" + strings.Repeat(" --- |", len(t.Headers)) + "\n")

	// Print rows.
	for _, row := range t.Rows {
		escapedRow := make([]string, len(row))
		for i, cell := range row {
			escapedRow[i] = strings.ReplaceAll(cell, "|", "&#124;") // Escape pipe characters.
		}
		sb.WriteString("| " + strings.Join(escapedRow, " | ") + " |\n")
	}

	return sb.String()
}

// Package md provides helper functions for generating Markdown content programmatically.
//
// It includes utilities for text formatting, creating lists, blockquotes, code blocks,
// links, images, and more.
//
// Highlights:
// - Supports basic Markdown syntax such as bold, italic, strikethrough, headers, and lists.
// - Manages multiline support in lists (e.g., bullet, ordered, and todo lists).
// - Includes advanced helpers like inline images with links and nested list prefixes.
//
// For a comprehensive example of how to use these helpers, see:
// https://gno.land/r/docs/moul_md
//
// # Sanitization contract
//
// Some helpers in this package sanitize their user-derived arguments
// INTERNALLY (via p/nt/markdown/sanitize/v0). When using these, pass
// raw user input — do NOT pre-wrap with sanitize.*, or you will
// double-wrap (the escapers are not idempotent and double-wrap is a
// bug):
//
//	Link, UserLink, Image, InlineImageWithLink, FootnoteDefinition,
//	LinkReferenceDefinition, CollapsibleSection (title only),
//	InlineCode, CodeBlock, LanguageCodeBlock, Blockquote
//
// The other helpers DO NOT sanitize — they are pure builders that
// wrap their input in markdown chrome. User-derived input reaches
// the output unmodified, so callers MUST wrap with sanitize.* at the
// call site:
//
//	Bold, Italic, Strikethrough, H1-H6, BulletList, BulletItem,
//	OrderedList, TodoList, TodoItem, Nested, Paragraph, Columns,
//	ColumnsN, HorizontalRule
//
// Examples:
//
//	// Sanitizing helper — pass raw:
//	out += md.Link(post.Title, post.URL)                                 // good
//	out += md.Link(sanitize.InlineText(post.Title), sanitize.URL(post.URL)) // BAD: double-wrap
//
//	// Non-sanitizing helper — wrap once:
//	out += md.H2(sanitize.InlineText(post.Title))                        // good
//	out += md.H2(post.Title)                                             // BAD: raw user input
//	out += md.H2(sanitize.InlineText(sanitize.InlineText(post.Title)))   // BAD: double-wrap
//
// Composition: outputs of sanitizing helpers are safe markdown chrome
// and can be embedded inside non-sanitizing helpers freely:
//
//	out += md.H2(md.Link(post.Title, post.URL))   // good — H2 doesn't re-escape Link's output
//
// The reverse is unsafe: do NOT embed a non-sanitizing helper's
// markdown chrome inside a sanitizing helper's arg, or the inner
// markdown gets re-escaped:
//
//	out += md.Link(md.Bold(post.Title), post.URL) // BAD: Link's internal sanitize
//	                                              // escapes the ** chars from md.Bold
package md

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// Bold returns bold text for markdown.
// Example: Bold("foo") => "**foo**"
func Bold(text string) string {
	return "**" + text + "**"
}

// Italic returns italicized text for markdown.
// Example: Italic("foo") => "*foo*"
func Italic(text string) string {
	return "*" + text + "*"
}

// Strikethrough returns strikethrough text for markdown.
// Example: Strikethrough("foo") => "~~foo~~"
func Strikethrough(text string) string {
	return "~~" + text + "~~"
}

// H1 returns a level 1 header for markdown.
// Example: H1("foo") => "# foo\n"
func H1(text string) string {
	return "# " + text + "\n"
}

// H2 returns a level 2 header for markdown.
// Example: H2("foo") => "## foo\n"
func H2(text string) string {
	return "## " + text + "\n"
}

// H3 returns a level 3 header for markdown.
// Example: H3("foo") => "### foo\n"
func H3(text string) string {
	return "### " + text + "\n"
}

// H4 returns a level 4 header for markdown.
// Example: H4("foo") => "#### foo\n"
func H4(text string) string {
	return "#### " + text + "\n"
}

// H5 returns a level 5 header for markdown.
// Example: H5("foo") => "##### foo\n"
func H5(text string) string {
	return "##### " + text + "\n"
}

// H6 returns a level 6 header for markdown.
// Example: H6("foo") => "###### foo\n"
func H6(text string) string {
	return "###### " + text + "\n"
}

// BulletList returns a bullet list for markdown.
// Example: BulletList([]string{"foo", "bar"}) => "- foo\n- bar\n"
func BulletList(items []string) string {
	var sb strings.Builder
	for _, item := range items {
		sb.WriteString(BulletItem(item))
	}
	return sb.String()
}

// BulletItem returns a bullet item for markdown.
// Example: BulletItem("foo") => "- foo\n"
func BulletItem(item string) string {
	var sb strings.Builder
	lines := strings.Split(item, "\n")
	sb.WriteString("- " + lines[0] + "\n")
	for _, line := range lines[1:] {
		sb.WriteString("  " + line + "\n")
	}
	return sb.String()
}

// OrderedList returns an ordered list for markdown.
// Example: OrderedList([]string{"foo", "bar"}) => "1. foo\n2. bar\n"
func OrderedList(items []string) string {
	var sb strings.Builder
	for i, item := range items {
		lines := strings.Split(item, "\n")
		sb.WriteString(strconv.Itoa(i+1) + ". " + lines[0] + "\n")
		for _, line := range lines[1:] {
			sb.WriteString("   " + line + "\n")
		}
	}
	return sb.String()
}

// TodoList returns a list of todo items with checkboxes for markdown.
// Example: TodoList([]string{"foo", "bar\nmore bar"}, []bool{true, false}) => "- [x] foo\n- [ ] bar\n  more bar\n"
func TodoList(items []string, done []bool) string {
	var sb strings.Builder
	for i, item := range items {
		sb.WriteString(TodoItem(item, done[i]))
	}
	return sb.String()
}

// TodoItem returns a todo item with checkbox for markdown.
// Example: TodoItem("foo", true) => "- [x] foo\n"
func TodoItem(item string, done bool) string {
	var sb strings.Builder
	checkbox := " "
	if done {
		checkbox = "x"
	}
	lines := strings.Split(item, "\n")
	sb.WriteString("- [" + checkbox + "] " + lines[0] + "\n")
	for _, line := range lines[1:] {
		sb.WriteString("  " + line + "\n")
	}
	return sb.String()
}

// Nested prefixes each line with a given prefix, enabling nested lists.
// Example: Nested("- foo\n- bar", "  ") => "  - foo\n  - bar\n"
func Nested(content, prefix string) string {
	lines := strings.Split(content, "\n")
	for i := range lines {
		if strings.TrimSpace(lines[i]) != "" {
			lines[i] = prefix + lines[i]
		}
	}
	return strings.Join(lines, "\n")
}

// Blockquote returns the text as a CommonMark blockquote.
// Example: Blockquote("foo\nbar") => "\n> foo\n> bar\n\n"
//
// Delegates to sanitize.Blockquote, which cleans the content (bidi-strip,
// CR/CRLF/U+2028/U+2029/NEL line-ending normalize, LRD strip, ref-link
// escape, block-marker escape, fence auto-close), line-prefixes each
// line with "> ", and wraps with "\n" / "\n\n" so the quote opens
// cleanly and cannot pull appended chrome into the quote via CM §5.2
// lazy continuation. Callers do NOT need to pre-wrap the input.
func Blockquote(text string) string {
	return sanitize.Blockquote(text)
}

// InlineCode wraps the given text as a CommonMark inline code span.
// Example: InlineCode("foo") => "`foo`"
//
// Delegates to sanitize.InlineCode, which cleans the input (bidi-strip,
// CR/CRLF + NEL + U+2028/U+2029 folded to single space, NUL→U+FFFD)
// and picks a backtick-run length that outscans any internal backticks.
// Callers do NOT need to pre-wrap the input.
func InlineCode(code string) string {
	return sanitize.InlineCode(code)
}

// CodeBlock creates a markdown code block.
// Example: CodeBlock("foo") => "```\nfoo\n```"
//
// Delegates to sanitize.CodeBlock, which cleans the content (bidi-strip,
// CR/CRLF normalize, NEL/U+2028/U+2029 fold, NUL→U+FFFD) and picks a
// fence wide enough to outscan any backticks in content. Callers do NOT
// need to pre-wrap content with another sanitize helper.
func CodeBlock(content string) string {
	return sanitize.CodeBlock(content)
}

// LanguageCodeBlock creates a markdown code block with language-specific syntax highlighting.
// Example: LanguageCodeBlock("go", "foo") => "```go\nfoo\n```"
//
// Delegates to sanitize.LanguageCodeBlock, which validates the language
// tag (charset ^[a-zA-Z0-9_+-]{1,32}$, falling back to a tagless fence
// if invalid) and cleans the content as CodeBlock does. Callers do NOT
// need to pre-wrap either argument.
func LanguageCodeBlock(language, content string) string {
	return sanitize.LanguageCodeBlock(language, content)
}

// HorizontalRule returns a horizontal rule for markdown.
// Example: HorizontalRule() => "---\n"
func HorizontalRule() string {
	return "---\n"
}

// Link returns a hyperlink for markdown.
// Example: Link("foo", "http://example.com") => "[foo](http://example.com)"
//
// The text and url args are sanitized internally — text via
// sanitize.InlineText, url via sanitize.URL (allowlists http/https/
// mailto/relative/fragment; rejects javascript:, data:, blob:, etc.).
// Callers do NOT need to pre-wrap either argument; double-wrapping is
// a bug (the inline-text escaper is non-idempotent).
//
// If the URL fails the scheme allowlist, the href is rendered empty —
// the link becomes inert rather than carrying a malicious destination.
func Link(text, url string) string {
	return "[" + sanitize.InlineText(text) + "](" + sanitize.URL(url) + ")"
}

// UserLink returns a user profile link for markdown.
// Example: UserLink("moul") => "[@moul](/u/moul)"
// Example: UserLink("g1blah...") => "[g1blah...](/u/g1blah...)"
//
// Validates the user identifier — if it matches the gno bech32 address
// pattern (g1...), produces an address-style link; otherwise tries the
// r/sys/users-charset username and produces an @-style link. Returns
// "" if the identifier matches neither — callers should treat "" as
// "skip the user mention" rather than emit a broken link.
func UserLink(user string) string {
	if addr := sanitize.BechString(user, "g"); addr != "" {
		return "[" + addr + "](/u/" + addr + ")"
	}
	if name := sanitize.UserName(user); name != "" {
		return "[@" + name + "](/u/" + name + ")"
	}
	return ""
}

// InlineImageWithLink creates an inline image wrapped in a hyperlink for markdown.
// Example: InlineImageWithLink("alt text", "image-url", "link-url") => "[![alt text](image-url)](link-url)"
//
// altText and imageUrl are sanitized via Image (sanitize.InlineText +
// sanitize.ImageURL); linkUrl is sanitized via sanitize.URL. Callers
// do NOT need to pre-wrap any argument.
func InlineImageWithLink(altText, imageUrl, linkUrl string) string {
	return "[" + Image(altText, imageUrl) + "](" + sanitize.URL(linkUrl) + ")"
}

// Image returns an image for markdown.
// Example: Image("foo", "http://example.com") => "![foo](http://example.com)"
//
// altText is sanitized via sanitize.InlineText, url via
// sanitize.ImageURL (allowlists http/https/relative + data:image/*;
// rejects mailto:, javascript:, data:text/html, etc.). Callers do NOT
// need to pre-wrap either argument.
func Image(altText, url string) string {
	return "![" + sanitize.InlineText(altText) + "](" + sanitize.ImageURL(url) + ")"
}

// FootnoteDefinition emits a GFM footnote definition — `[^name]: body` —
// for a footnote that is referenced elsewhere in the document by
// `[^name]`.
//
// Example: FootnoteDefinition("note1", "Long form of the citation.")
// renders as:
//
//	[^note1]:
//	    Long form of the citation.
//
// The `name` is validated as a FootnoteLabel (^[A-Za-z0-9_-]{1,64}$);
// `text` is user-supplied multi-paragraph prose, sanitized via Block.
// An invalid name or empty body returns "".
//
// Delegates to sanitize.FootnoteDefinition. Callers do NOT need to
// pre-wrap either argument.
func FootnoteDefinition(name, text string) string {
	return sanitize.FootnoteDefinition(name, text)
}

// LinkReferenceDefinition emits a CommonMark link reference definition
// (CM §4.7) — `[label]: url "title"` — for a reference link that is
// invoked elsewhere by `[text][label]` or by the shortcut form
// `[label]`.
//
// Example: LinkReferenceDefinition("r/docs/help", "/r/docs/help", "")
// renders as:
//
//	[r/docs/help]: /r/docs/help
//
// The `label` is validated as a FootnoteLabel (^[A-Za-z0-9_-]{1,64}$);
// `url` is sanitized via URL (allowlist); `title` is sanitized via
// LinkTitle. An invalid label or rejected URL returns "".
//
// Realms should choose a namespaced label using dashes
// (e.g. `r-myrealm-help`) so that shortcut-reference invocations from
// user content can't collide with bare words a user is likely to write.
// `/` is not in the FootnoteLabel charset.
//
// Delegates to sanitize.LinkReferenceDefinition. Callers do NOT need to
// pre-wrap any argument.
func LinkReferenceDefinition(label, url, title string) string {
	return sanitize.LinkReferenceDefinition(label, url, title)
}

// Paragraph wraps the given text in a Markdown paragraph.
// Example: Paragraph("foo") => "foo\n"
func Paragraph(content string) string {
	return content + "\n\n"
}

// CollapsibleSection creates a collapsible section for markdown using
// HTML <details> and <summary> tags.
// Example:
// CollapsibleSection("Click to expand", "Hidden content")
// =>
// <details><summary>Click to expand</summary>
//
// Hidden content
// </details>
//
// The title argument is sanitized via sanitize.HTMLEscape (it lands in
// an HTML element body inside <summary>, not a markdown context — so
// HTML entity escaping is the correct policy, not markdown backslash
// escaping). The content argument is passed through unchanged because
// <details> with a blank-line-separated body allows markdown inside
// (CM §4.6); callers must pre-wrap content with sanitize.Block if it
// derives from user input.
func CollapsibleSection(title, content string) string {
	return "<details><summary>" + sanitize.HTMLEscape(title) + "</summary>\n\n" + content + "\n</details>\n"
}

// EscapeURL escapes characters in a URL for use in markdown link syntax.
//
// Deprecated: use sanitize.URL (for link href) or sanitize.ImageURL
// (for image src) directly. EscapeURL previously only percent-encoded
// ( and ) and did not validate the URL scheme — a security footgun
// (EscapeURL("javascript:alert(1)") returned a working XSS payload).
// It now delegates to sanitize.URL, which allowlists schemes (rejects
// javascript:, data:text/html, vbscript:, blob:, etc.) and
// percent-encodes all unsafe bytes (including the ( ) this function
// handled). The other helpers in this package (Link, UserLink, Image,
// InlineImageWithLink) sanitize their URL args internally now, so you
// rarely need to call any URL-escape helper directly.
//
// Behavior change vs. the original implementation: invalid schemes
// now return "" instead of passing through with ( ) escaped. Non-ASCII
// bytes get percent-encoded to standard RFC 3986 wire form instead of
// passing through as raw UTF-8.
func EscapeURL(url string) string {
	return sanitize.URL(url)
}

// EscapeText escapes special Markdown characters in regular text for
// use in inline contexts.
//
// Deprecated: use sanitize.InlineText directly. EscapeText was
// INCOMPLETE — it missed \, #, <, & and did not strip bidi/zero-width
// characters, replace NUL with U+FFFD, or normalize line endings.
// User input could inject backslash escapes (\* cancels neighboring
// escapes), autolinks (<https://x>), raw HTML (<script>), HTML entity
// references (&amp;), and bidi spoofing (RLO before an address). It
// now delegates to sanitize.InlineText. The other helpers in this
// package (Link, UserLink, Image, InlineImageWithLink, CollapsibleSection)
// sanitize their text args internally now, so you rarely need to call
// any inline-text-escape helper directly.
//
// Behavior change vs. the original implementation: \, #, <, & are now
// escaped; | is no longer escaped (the original was over-escaping —
// outside GFM table-cell context, | is markdown-inert; for table
// cells use sanitize.TableCell which adds the | escape on top of the
// inline-text set). Bidi controls are stripped, NUL becomes U+FFFD,
// and line endings normalize.
func EscapeText(text string) string {
	return sanitize.InlineText(text)
}

// Columns returns a formatted row of columns using the Gno syntax.
// If you want a specific number of columns per row (<=4), use ColumnsN.
// Check /r/docs/markdown#columns for more info.
// If padded=true & the final <gno-columns> tag is missing column content, an empty
// column element will be placed to keep the cols per row constant.
// Padding works only with colsPerRow > 0.
//
// Example:
//
//	Columns([]string{"A", "B"}, false)
//	// Returns:
//	// <gno-columns>
//	// A
//	// <gno-columns-sep>
//	// B
//	// </gno-columns>
func Columns(contentByColumn []string, padded bool) string {
	if len(contentByColumn) == 0 {
		return ""
	}
	maxCols := 4
	if padded && len(contentByColumn)%maxCols != 0 {
		missing := maxCols - len(contentByColumn)%maxCols
		contentByColumn = append(contentByColumn, make([]string, missing)...)
	}

	var sb strings.Builder
	sb.WriteString("<gno-columns>\n")

	for i, column := range contentByColumn {
		if i > 0 {
			sb.WriteString("<gno-columns-sep>\n")
		}
		sb.WriteString(column + "\n")
	}

	sb.WriteString("</gno-columns>\n")
	return sb.String()
}

const maxColumnsPerRow = 4

// ColumnsN splits content into multiple rows of N columns each and formats them.
// If colsPerRow <= 0, all items are placed in one <gno-columns> block.
// If padded=true & the final <gno-columns> tag is missing column content, an empty
// column element will be placed to keep the cols per row constant.
// Padding works only with colsPerRow > 0.
// Note: On standard-size screens, gnoweb handles a max of 4 cols per row.
//
// Example:
//
//	ColumnsN([]string{"A", "B", "C"}, 2, false)
//	// Returns:
//	// <gno-columns>
//	// A
//	// <gno-columns-sep>
//	// B
//	// </gno-columns>
//	// <gno-columns>
//	// C
//	// </gno-columns>
func ColumnsN(content []string, colsPerRow int, padded bool) string {
	if len(content) == 0 {
		return ""
	}
	if colsPerRow <= 0 {
		return Columns(content, padded)
	}

	var sb strings.Builder
	// Case 2: Multiple blocks with max 4 columns
	for i := 0; i < len(content); i += colsPerRow {
		end := i + colsPerRow
		if end > len(content) {
			end = len(content)
		}
		row := content[i:end]

		// Add padding if needed
		if padded && len(row) < colsPerRow {
			row = append(row, make([]string, colsPerRow-len(row))...)
		}

		sb.WriteString(Columns(row, false))
	}
	return sb.String()
}

// Package mdtable provides a simple way to create Markdown tables.
//
// Example usage:
//
//	import "gno.land/p/moul/mdtable/v0"
//
//	func Render(path string) string {
//	    table := mdtable.Table{
//	        Headers: []string{"ID", "Title", "Status", "Date"},
//	    }
//	    table.Append([]string{"#1", "Add a new validator", "succeed", "2024-01-01"})
//	    table.Append([]string{"#2", "Change parameter", "timed out", "2024-01-02"})
//	    return table.String()
//	}
//
// Output:
//
//	| ID | Title | Status | Date |
//	| --- | --- | --- | --- |
//	| #1 | Add a new validator | succeed | 2024-01-01 |
//	| #2 | Change parameter | timed out | 2024-01-02 |
package mdtable

import (
	"strings"
)

type Table struct {
	Headers []string
	Rows    [][]string
	// XXX: optional headers alignment.
}

func (t *Table) Append(row []string) {
	t.Rows = append(t.Rows, row)
}

func (t Table) String() string {
	// XXX: switch to using text/tabwriter when porting to Gno to support
	// better-formatted raw Markdown output.

	if len(t.Headers) == 0 && len(t.Rows) == 0 {
		return ""
	}

	var sb strings.Builder

	if len(t.Headers) == 0 {
		t.Headers = make([]string, len(t.Rows[0]))
	}

	// Print header.
	sb.WriteString("| " + strings.Join(t.Headers, " | ") + " |\n")
	sb.WriteString("|" + strings.Repeat(" --- |", len(t.Headers)) + "\n")

	// Print rows.
	for _, row := range t.Rows {
		escapedRow := make([]string, len(row))
		for i, cell := range row {
			escapedRow[i] = strings.ReplaceAll(cell, "|", "&#124;") // Escape pipe characters.
		}
		sb.WriteString("| " + strings.Join(escapedRow, " | ") + " |\n")
	}

	return sb.String()
}

package nft

import (
	"chain/runtime"
	"strconv"

	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft/v0"
)

// TokenURI returns a JSON string with the metadata of a Settler (OpenSea style).
// The `image` is the gnome SVG, encoded in a data URI, and the `external_url` is
// the page of this realm that shows the token, so that an app that lists a Settler
// can link back to the realm.
func TokenURI(settlerID int) string {
	t := TraitsOf(settlerID)

	var attrs string
	for i, attr := range t.Attributes() {
		if i > 0 {
			attrs += ","
		}

		attrs += `{"trait_type":"` + attr.Type + `","value":"` + attr.Value + `"}`
	}

	return `{"name":"Settler #` + strconv.Itoa(settlerID) + `",` +
		`"description":"Soulbound gnome of the early settlers of Gno.land. ` + nft.Credits + `",` +
		`"image":"` + nft.RenderDataURI(t, nft.Options{Size: nft.CanonicalSize}) + `",` +
		`"external_url":"` + ExternalURL(settlerID) + `",` +
		`"attributes":[` + attrs + `]}`
}

// ExternalURL returns the URL to a Settler profile page.
func ExternalURL(settlerID int) string {
	return "https://" + runtime.ChainDomain() + realmPath + ":token/" + strconv.Itoa(settlerID)
}

package nft

import (
	"chain"
	"chain/runtime"
	"crypto/merkle"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/bloom/v0"
	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft/v0"
	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/ownable/v0"
)

const (
	// Name is the NFT token's name.
	Name = "Settlers"

	// Symbol is the NFT token's symbol.
	Symbol = "SETTLER"

	// Capacity is the total number of Settlers that can be minted.
	capacity = 3000

	// Max nonce is how many gnomes are tried for a token before giving up,
	// when the ones that come out are already taken.
	maxNonce = 64

	// Max aunts is the longest proof accepted.
	maxAunts = 40
)

var (
	// Admin account for the realm.
	// This account is only valid to set snapshot params, once setted minting
	// can start and the account becomes obsolete when the first NFT is minted.
	Admin *ownable.Ownable

	// Supply cap is the number of Settlers that can be minted.
	supplyCap = capacity

	// Root is the Merkle root value.
	root []byte

	// Total is the total number of leaves of the list of elegible accounts.
	total int

	// Tokens has every token, by ID (zero-padded, so it is in mint order).
	tokens = bptree.NewBPTree32()

	// Claimed has the ID of the token for each account.
	claimed = bptree.NewBPTree32()

	// Seen has the packed traits of the tokens, so that two Settlers are never the same.
	seen = newTraitsFilter()

	// Realm path is the path of this realm.
	realmPath string
)

// Token represents a Settler.
type token struct {
	owner  address
	traits uint32
}

func init(cur realm) {
	realmPath = strings.TrimPrefix(cur.PkgPath(), runtime.ChainDomain())
	Admin = ownable.NewWithAddress(cur.Previous().Address())

	// Announce the new collection
	chain.Emit(
		"NewToken",
		"token", CollectionID(),
		"name", Name,
		"symbol", Symbol,
	)
}

// SetSnapshot opens the mint.
// It sets the Merkle root of the list of eligible accounts, in hex, and the
// number of accounts in the list. Only the owner can call it.
// It can be called again to correct a mistake until the first Settler is minted,
// from then on the list is frozen.
func SetSnapshot(cur realm, rootHex string, count int) {
	Admin.AssertOwnedBy(cur.Previous().Address())

	if tokens.Size() > 0 {
		panic("the snapshot is frozen: Settlers were already minted")
	}

	bz, err := hex.DecodeString(rootHex)
	if err != nil || len(bz) != 32 {
		panic("the root must be 32 bytes in hex")
	}

	if count < 1 {
		panic("the list must have at least one account")
	}

	root = bz
	total = count
	chain.Emit(
		"SnapshotSet",
		"root", rootHex,
		"total", strconv.Itoa(count),
	)
}

// Mint mints a Settler to the caller and returns its id.
//
// The proof shows that the caller is in the list of eligible accounts.
// Proof format is "<index>.<aunts>".
func Mint(cur realm, proof string) int {
	if len(root) == 0 {
		panic("the mint is not open yet")
	}

	minted := tokens.Size()
	if minted >= supplyCap {
		panic("sold out")
	}

	caller := cur.Previous().Address()
	if claimed.Has(caller.String()) {
		panic("this account has already minted")
	}

	index, aunts, err := splitProof(proof)
	if err != "" {
		panic(err)
	}

	if !merkle.VerifySimpleProof(root, []byte(caller), index, total, aunts) {
		panic("the proof is not valid for this account: " + caller.String())
	}

	settlerID := minted + 1
	var packed uint32
	for nonce := 0; ; nonce++ {
		if nonce == maxNonce {
			panic("could not find a new gnome, try again")
		}

		seed := generateSeed(caller, runtime.ChainHeight(), settlerID, nonce)
		traits := nft.NewTraits(seed)
		packed = nft.Pack(traits.Normalized())
		if !seen.ContainsString(strconv.FormatUint(uint64(packed), 10)) {
			break
		}
	}

	tokens.Set(makeKey(settlerID), token{owner: caller, traits: packed})
	seen.AddString(strconv.FormatUint(uint64(packed), 10))
	claimed.Set(caller.String(), settlerID)
	chain.Emit(
		"Transfer",
		"token", CollectionID(),
		"from", "",
		"to", caller.String(),
		"tokenId", strconv.Itoa(settlerID),
	)
	return settlerID
}

// Cap returns the number of Settlers that can be minted.
func Cap() int { return supplyCap }

// TotalSupply returns the number of Settlers minted so far.
func TotalSupply() int { return tokens.Size() }

// MerkleRoot returns the Merkle root of the list of eligible accounts, in hex.
func MerkleRoot() string { return hex.EncodeToString(root) }

// Total returns the number of eligible accounts in the list.
func Total() int { return total }

// CollectionID returns the ID that the events use for this collection.
func CollectionID() string {
	return runtime.ChainDomain() + realmPath + "." + Symbol + ".0000000"
}

// OwnerOf returns the owner account of a Settler.
func OwnerOf(settlerID int) address { return tokenOf(settlerID).owner }

// BalanceOf returns the number of Settlers of an account (0 or 1).
func BalanceOf(addr address) int {
	if claimed.Has(addr.String()) {
		return 1
	}
	return 0
}

// TokenOf returns the ID of the Settler of an account, or 0 if it has none.
func TokenOf(addr address) int {
	v := claimed.Get(addr.String())
	if v == nil {
		return 0
	}
	return v.(int)
}

// TraitsOf returns the traits of a Settler.
func TraitsOf(settlerID int) nft.Traits { return nft.Unpack(tokenOf(settlerID).traits) }

func tokenOf(settlerID int) token {
	v := tokens.Get(makeKey(settlerID))
	if v == nil {
		panic("token not found")
	}
	return v.(token)
}

func newTraitsFilter() *bloom.Bloom {
	m := uint64(28756) // bits
	k := uint64(7)     // hashes
	return bloom.NewWithMK(m, k)
}

func generateSeed(caller address, height int64, settlerID, nonce int) string {
	input := caller.String() + ":" + strconv.FormatInt(height, 10) + ":" +
		strconv.Itoa(settlerID) + ":" + strconv.Itoa(nonce)
	sum := sha256.Sum256([]byte(input))
	return hex.EncodeToString(sum[:])
}

func splitProof(proof string) (int, []byte, string) {
	dot := strings.Index(proof, ".")
	if dot < 1 {
		return 0, nil, "the proof must be <index>.<aunts>"
	}

	index, err := strconv.Atoi(proof[:dot])
	if err != nil || index < 0 || index >= total {
		return 0, nil, "the index of the proof is not valid"
	}

	aunts, err := hex.DecodeString(proof[dot+1:])
	if err != nil || len(aunts)%32 != 0 || len(aunts) > 32*maxAunts {
		return 0, nil, "the aunts of the proof must be hashes of 32 bytes in hex"
	}
	return index, aunts, ""
}

func makeKey(settlerID int) string {
	s := strconv.Itoa(settlerID)
	return strings.Repeat("0", 5-len(s)) + s
}

package nft

import (
	"strconv"

	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft/v0"
	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/md/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
)

const (
	// Gallery width is the width/height of gallery Settler images.
	galleryWidth = 96

	// Detail width is the width/height of Settler the image for detail views.
	detailWidth = 256

	// Gallery length is the number of last minted Settlers of the home page.
	galleryLen = 5
)

// Render renders the realm.
//
// By default renders the state of the mint and the last minted Settlers.
//
// Paths:
//   - `token/{id}`: A Settler with its traits and its owner.
//   - `addr/{address}`: The Settler of an account.
func Render(path string) string {
	router := mux.NewRouter()
	router.NotFoundHandler = func(res *mux.ResponseWriter, _ *mux.Request) {
		res.Write("Path not found")
	}

	router.HandleFunc("", renderHome)
	router.HandleFunc("token/{id}", renderToken)
	router.HandleFunc("addr/{addr}", renderAddr)

	return router.Render(path)
}

func renderHome(res *mux.ResponseWriter, _ *mux.Request) {
	res.Write(md.H1("Settlers"))
	res.Write(md.Paragraph(
		"Soulbound pixel-art gnomes for the early settlers of Gno.land. " +
			"Every account that had at least 15 GNOT at the launch of `gnoland-1` can mint one, " +
			"first come first served. A Settler can't be transferred.",
	))

	minted := TotalSupply()
	if len(root) == 0 {
		res.Write(md.Paragraph("The mint is not open yet."))
	} else {
		res.Write(md.Paragraph(
			md.BulletItem(md.Bold("Minted:")+" "+strconv.Itoa(minted)+" of "+strconv.Itoa(supplyCap)) +
				md.BulletItem(md.Bold("Eligible accounts:")+" "+strconv.Itoa(total)) +
				md.BulletItem(md.Bold("Merkle root:")+" "+md.InlineCode(MerkleRoot())),
		))

		res.Write(md.Paragraph(
			"To mint, get your proof from the list of eligible accounts and call `Mint` with it; " +
				"the account that signs the transaction is the one that gets the Settler.",
		))
	}

	if minted > 0 {
		res.Write(md.H2("Last Settlers"))
		tokens.ReverseIterateByOffset(0, galleryLen, func(key string, value any) bool {
			settlerID, _ := strconv.Atoi(key)
			alt := "Settler #" + strconv.Itoa(settlerID)
			img := image(alt, nft.Unpack(value.(token).traits), galleryWidth)
			res.Write("[" + img + "](" + tokenPath(settlerID) + ") ")
			return false
		})
		res.Write("\n\n")
	}

	res.Write(footer())
}

func renderToken(res *mux.ResponseWriter, req *mux.Request) {
	rawSettlerID := req.GetVar("id")
	settlerID, err := strconv.Atoi(rawSettlerID)
	if err != nil || settlerID < 1 || settlerID > TotalSupply() {
		res.Write(md.Paragraph("Settler not found."))
		res.Write(md.Paragraph(md.Link("Home", realmPath)))
		return
	}

	title := "Settler #" + rawSettlerID
	res.Write(md.H1(title))
	t := TraitsOf(settlerID)
	res.Write(image(title, t, detailWidth) + "\n\n")

	owner := OwnerOf(settlerID).String()
	res.Write(md.Paragraph(
		"Owner: " + md.Link(owner, realmPath+":addr/"+owner) +
			" · soulbound: it can't be transferred",
	))

	res.Write("| Trait | Value |\n| --- | --- |\n")
	for _, attr := range t.Attributes() {
		res.Write("| " + attr.Type + " | " + attr.Value + " |\n")
	}
	res.Write("\n")

	res.Write(md.Paragraph(md.Link("Home", realmPath)))
	res.Write(footer())
}

func renderAddr(res *mux.ResponseWriter, req *mux.Request) {
	addr := sanitize.BechString(req.GetVar("addr"), "g")
	if addr == "" {
		res.Write(md.Paragraph("Not a valid address."))
		res.Write(md.Paragraph(md.Link("Home", realmPath)))
		return
	}

	settlerID := TokenOf(address(addr))
	if settlerID == 0 {
		res.Write(md.H1("Settler of " + md.InlineCode(addr)))
		res.Write(md.Paragraph("This account has not minted a Settler."))
		res.Write(md.Paragraph(md.Link("Home", realmPath)))
		return
	}

	res.Write(md.H1("Settler of " + md.InlineCode(addr)))
	res.Write("[" + image("Settler #"+strconv.Itoa(settlerID), TraitsOf(settlerID), detailWidth) + "](" + tokenPath(settlerID) + ")\n\n")
	res.Write(md.Paragraph(md.Link("Settler #"+strconv.Itoa(settlerID), tokenPath(settlerID)) + " · " + md.Link("Home", realmPath)))
	res.Write(footer())
}

func image(alt string, t nft.Traits, width int) string {
	return "![" + alt + "](" + nft.RenderDataURI(t, nft.Options{Size: width}) + ")"
}

func tokenPath(settlerID int) string {
	return realmPath + ":token/" + strconv.Itoa(settlerID)
}

func footer() string {
	return md.Blockquote(nft.Credits)
}

package avatar

import (
	"strconv"

	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft/v0"
	settlers "gno.land/r/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft"
)

const (
	// MinSize is the minimum size allowed for an avatar in pixels.
	MinSize = 32

	// MaxSize is the maximum size allowed for an avatar in pixels.
	MaxSize = 2048
)

// SVG returns the SVG document of the Settler of an address, or an empty text if it has none.
//
// The size is the width and height in pixels of the square image, from 32 to 2048 (multiples of 32 keep
// every art pixel as a whole number of screen pixels). A size of 0 or less leaves out the width and the
// height, so that the image scales to its container. If transparent is true, the image has no background.
func SVG(addr address, size int, transparent bool) string {
	if settlerID, traits := lookup(addr); settlerID != -1 {
		return nft.RenderSVG(traits, options(size, transparent))
	}
	return ""
}

// URI returns the image of the Settler of an address as a "data:image/svg+xml;charset=utf-8," URI, that can
// be used as the source of an image or as the address of a Markdown image, or an empty text if it has none.
// The size and transparent are the same as in SVG.
func URI(addr address, size int, transparent bool) string {
	if settlerID, traits := lookup(addr); settlerID != -1 {
		return nft.RenderDataURI(traits, options(size, transparent))
	}
	return ""
}

// Markdown returns the avatar of an address as a Markdown image, or an empty text if it has none:
//
//	![Settler #12](data:image/svg+xml;charset=utf-8,...)
//
// The size and transparent are the same as in SVG.
func Markdown(addr address, size int, transparent bool) string {
	if settlerID, traits := lookup(addr); settlerID != -1 {
		uri := nft.RenderDataURI(traits, options(size, transparent))
		return "![Settler #" + strconv.Itoa(settlerID) + "](" + uri + ")"
	}
	return ""
}

// lookup returns the ID and traits of the Settler of an address, or -1 and a zero-value Traits if it has none.
func lookup(addr address) (int, nft.Traits) {
	settlerID := settlers.TokenOf(addr)
	if settlerID == 0 {
		return -1, nft.Traits{}
	}

	traits := settlers.TraitsOf(settlerID)
	return settlerID, traits
}

// options builds the nft.Options for an image; size is clamped between MinSize and MaxSize (0 or less is
// left as 0, so the image has no fixed size and scales to its container), and transparent controls whether
// the background is drawn.
func options(size int, transparent bool) nft.Options {
	switch {
	case size <= 0:
		size = 0
	case size < MinSize:
		size = MinSize
	case size > MaxSize:
		size = MaxSize
	}

	return nft.Options{
		Size:         size,
		NoBackground: transparent,
	}
}

package avatar

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/md/v0"
	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/mdtable/v0"
	"gno.land/p/nt/mux/v0"
	settlers "gno.land/r/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft"
)

const (
	// Sample size is the size in pixels of the avatars in the pages.
	sampleSize = 48

	// Samples is how many avatars the home page shows.
	samples = 6

	// Snippet contains a package usage snippet.
	snippet = "import \"gno.land/r/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/avatar\"\n\n" +
		"func row(addr address) string {\n\treturn avatar.Markdown(addr, 32, true) " +
		"+ \" \" + addr.String()\n}\n"
)

var realmPath string

func init(cur realm) {
	realmPath = strings.TrimPrefix(cur.PkgPath(), runtime.ChainDomain())
}

// Render renders the realm.
//
// By default renders what this realm is, how to use it, and some avatars.
//
// Paths:
//   - `svg/{address}`: The SVG of the Settler of an address.
//   - `md/{address}`: The Markdown that Markdown returns for an address, rendered, with the same parameters.
func Render(path string) string {
	router := mux.NewRouter()
	router.NotFoundHandler = func(res *mux.ResponseWriter, _ *mux.Request) {
		res.Write("Path not found")
	}

	router.HandleFunc("", renderHome)
	router.HandleFunc("svg/{addr}", renderSVG)
	router.HandleFunc("md/{addr}", renderMarkdown)

	return router.Render(path)
}

func renderHome(res *mux.ResponseWriter, _ *mux.Request) {
	res.Write(md.H1("Settler avatars"))
	res.Write(md.Paragraph(
		"The " + md.Link("Settlers", "/r/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft") +
			" of an address as an avatar, for other realms and for web apps.",
	))

	res.Write(md.H2("From a realm"))
	res.Write(md.LanguageCodeBlock("go", snippet))

	table := mdtable.Table{Headers: []string{"Function", "Description"}}
	table.Append([]string{
		"Markdown(addr, size, transparent)",
		"The image, or an empty text if there is none",
	})
	table.Append([]string{
		"SVG(addr, size, transparent)",
		"The SVG document, or an empty text if there is none",
	})
	table.Append([]string{
		"URI(addr, size, transparent)",
		"The same image as a data URI",
	})
	res.Write(table.String() + "\n")

	res.Write(md.Paragraph(
		"The size is in pixels, from 32 to 2048, and 0 leaves it to the container. " +
			"With transparent the image has no background. Every call draws the image again and " +
			"costs gas (about 6 to 8 million), so use it in `Render` and not in a transaction.",
	))

	res.Write(md.H2("From a web app"))
	res.Write(md.Paragraph("Ask the node for the page of an address, with `vm/qrender`, and use what it returns as an image: " +
		md.InlineCode(realmPath+":svg/{address}?size=64&transparent=1") + ". It is empty if the address has no Settler."))

	if n := settlers.TotalSupply(); n > 0 {
		res.Write(md.H2("Last Settlers"))

		for id := n; id > 0 && id > n-samples; id-- {
			owner := settlers.OwnerOf(id)
			table := mdtable.Table{Headers: []string{"", ""}}
			table.Append([]string{
				Markdown(owner, sampleSize, false),
				md.InlineCode(owner.String()),
			})
			res.Write(table.String() + "\n")
		}
	}
}

func renderSVG(res *mux.ResponseWriter, req *mux.Request) {
	svg := SVG(address(req.GetVar("addr")), sizeParam(req), transparentParam(req))
	res.Write(svg)
}

func renderMarkdown(res *mux.ResponseWriter, req *mux.Request) {
	size := sizeParam(req)
	if size == 0 {
		size = sampleSize
	}

	addr := req.GetVar("addr")
	if !address(addr).IsValid() {
		res.Write(md.Paragraph("Not a valid address."))
		res.Write(md.Paragraph(md.Link("Home", realmPath)))
		return
	}

	res.Write(md.H1("Avatar of " + md.InlineCode(addr)))
	res.Write(md.Paragraph(Markdown(address(addr), size, transparentParam(req))))
	res.Write(md.Paragraph(md.Link("Home", realmPath)))
}

func sizeParam(req *mux.Request) int {
	size, err := strconv.Atoi(req.Query.Get("size"))
	if err != nil {
		return 0
	}
	return size
}

func transparentParam(req *mux.Request) bool {
	v := req.Query.Get("transparent")
	return v == "1" || v == "true"
}
